  "loc.gpsTracker": "🛰️ Traceur GPS",
  "loc.guide1": "Installer l’app <b>« Traccar Client »</b> (App Store ou Google Play, gratuite).",
  "loc.guide2": "Dans l’app, saisir sous <b>ID de l’appareil</b> (Device identifier) :",
  "loc.guide3": "Saisir sous <b>URL du serveur</b> :",
  "loc.guide4": "Précision <b>Moyenne</b>, distance <b>50 m</b>. L’app n’envoie alors que lorsque tu bouges – rien à l’arrêt. S’il y a d’autres champs (intervalle, heartbeat), heartbeat désactivé ou 0.",
  "loc.guide5": "Autoriser l’accès à la position : <b>Toujours</b> et <b>Position exacte</b> activée.",
  "loc.guide6": "Activer l’interrupteur <b>Service / Suivi</b> et <b>le laisser toujours activé</b> – c’est fini. Désormais tu contrôles tout dans pinn. : « Envoyer en continu » activé ou non, « Envoyer une fois » et SOS. Tant que « Envoyer en continu » est désactivé, personne ne voit ta position et pinn. n’enregistre aucun trajet.",
  "loc.guideIntro": "Sans autre app, « 📍 Partager la position » fonctionne directement dans pinn. – mais seulement tant que pinn. est ouvert. Pour que la position arrive aussi pinn. fermé et écran verrouillé, l’app gratuite « Traccar Client » l’envoie directement à pinn. (aucun serveur Traccar nécessaire). Identique sur iPhone et Android.",
  "loc.h025013Watch5093": ", H02 5013, Watch 5093, Teltonika 5027. Ce port doit être redirigé vers le NAS dans la FRITZ!Box, car le traceur se connecte via le réseau mobile.",
