  "loc.setup": "Configuration · {famDeviceName}",
  "loc.setupIntro": "Les téléphones n’ont besoin de rien d’autre : chacun peut partager directement dans pinn. sous « Ma position ». En arrière-plan (pinn. fermé), le téléphone envoie avec l’app gratuite « Traccar Client » (iPhone et Android) – directement à pinn., aucun serveur Traccar n’est nécessaire. Seuls les traceurs GPS avec carte SIM (p. ex. au collier) ont besoin du conteneur « traccar ». Les positions restent sur votre NAS.",
