  "settings.calendar.fromFamily#wg": "de la colocation · pinn.",
  "settings.calendar.info": "Chaque profil se connecte avec son propre compte iCloud ou Google et coche les calendriers : « Pour moi » n'est vu que par ton profil, « Famille » est vu et utilisé par toute la famille. Les autres voient seulement de quel compte vient un calendrier familial – masqué, p. ex. m**l@g***l.com. Les rendez-vous se créent, modifient, déplacent et se mettent en attente hors ligne comme d'habitude et vont directement dans iCloud ou Google (donc sur le téléphone). Synchronisation toutes les 15 minutes ou avec « Mettre à jour ». Sans compte, un calendrier uniquement sur votre serveur pinn. fonctionne aussi. Rappels et résumé du jour par push : les rendez-vous privés seulement à toi.",
