  "smart.haTip1": "Roborock : créer l'appareil « Robot aspirateur », choisir le robot (vacuum.…) en haut – pinn. charge les pièces depuis la carte. Par action « Nettoyage de pièce » avec pièces et mode (aspirer, aspirer & laver, laver). « Pièce de la tâche » prend la pièce du nettoyage ménager – les noms doivent être les mêmes que dans l'app Roborock.",
